/// <summary>
/// SalesOrderHeaderCDSEntity COC class
/// </summary>
[ExtensionOf(tableStr(SalesOrderHeaderCDSEntity))]
final class METSalesOrderHeaderCDSEntity_Extension
{
}

Method.Source:
    /// <summary>
    /// CoC method for InsertEntityDataSource method
    /// </summary>
    /// <param name = "_entityCtx">Param of type DataEntityRuntimeContext</param>
    /// <param name = "_dataSourceCtx">Param of type DataEntityDataSourceRuntimeContext</param>
    /// <returns>true of false</returns>
    public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
    {
        SalesTable                      metSalesTableStd;
        //MetSalesOrderTypes              metSalesOrderTypes; //CB170_SalesOrderTypes remove logic as fields are removed
        MCRHoldCodeTrans                metMCRHoldCodeTrans;
        METSalesTable                   metSalesTable;
        boolean                         metModified;
        SalesOrderHeaderV2Entity        metSalesOrderHeaderEntityStd;
        METSalesOrderCDSEntityHelper    metSalesOrderCDSEntityHelper   = new METSalesOrderCDSEntityHelper();
        date                            metCurrentDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderHeaderCDSEntity, SalesOrderHeaderV2Entity))
        {
            metSalesOrderHeaderEntityStd    = _dataSourceCtx.getBuffer();
            //CB170_SalesOrderTypes logic to remove
            //metSalesOrderTypes  = MetSalesOrderTypes::find(metSalesOrderHeaderEntityStd.METSalesOrderType);

            if(metSalesOrderHeaderEntityStd.METReleaseDate == dateNull())
            {
                metSalesOrderHeaderEntityStd.METReleaseDate = metCurrentDate;
                metModified = true;
            }
            /*
            CB170_SalesOrderTypes remove logic as fields are removed
            if ((metSalesOrderTypes.OrderOnHold && metSalesOrderHeaderEntityStd.METReleaseDate > metCurrentDate ) ||
                metSalesOrderTypes.ReservationApproach == METReservationApproach::Manual ||
                metSalesOrderTypes.OrderReserve == NoYes::Yes )
            {
                metSalesOrderHeaderEntityStd.METReservation         = ItemReservation::None;
                metSalesOrderHeaderEntityStd.METOrderExtractStatus  = METOrderExtractStatus::None;
                metModified = true;
                _dataSourceCtx.setBuffer(metSalesOrderHeaderEntityStd);
            }
            */

            if (metSalesOrderCDSEntityHelper.checkLicenseOnSalesHeader(metSalesOrderHeaderEntityStd))
            {
                metModified = true;
            }

            _dataSourceCtx.setBuffer(metSalesOrderHeaderEntityStd);
        }

        boolean ret = next insertEntityDataSource(_entityCtx, _dataSourceCtx);

        if (_dataSourceCtx.name() == dataentitydatasourcestr(SalesOrderHeaderCDSEntity, SalesOrderHeaderV2Entity))
        {
            metSalesTableStd = SalesTable::find(this.SalesOrderNumber);

            select firstonly metSalesTableStd
                where metSalesTableStd.SalesId == this.SalesOrderNumber
                outer join ReleaseDate from metSalesTable
                where metSalesTable.SalesTable == metSalesTableStd.RecId;

            if (metSalesTableStd.RecId)
            {
                ttsbegin;
                metSalesTableStd.selectForUpdate(true);

                if(metModified)
                {
                    metSalesTableStd.METOrderExtractStatus    = METOrderExtractStatus::Open;
                }

                /// CB_202 SalesQuota changes by Akshay
               // metSalesTableStd.MatchingAgreement = this.metGetSalesAgreement(metSalesTableStd.CustAccount, metSalesTableStd.ShippingDateRequested);

                metSalesTableStd.update();
                ttscommit;

            }
            /*
            CB170_SalesOrderTypes remove logic as fields are removed
            if (metSalesOrderTypes.OrderOnHold && 
                metSalesTable.ReleaseDate > metCurrentDate &&
                metSalesTableStd.Reservation == ItemReservation::None)
            {
                metMCRHoldCodeTrans.InventRefId     = metSalesTableStd.SalesId;
                metMCRHoldCodeTrans.MCRHoldCode     = metSalesOrderTypes.OrderOnHold;
                metMCRHoldCodeTrans.insert();
            }
            */
        }
    
        return ret;
    }

    private AgreementHeaderRecId metGetSalesAgreement(CustAccount _custAccount, SalesShippingDateRequested _shippingDateRequested)
    {
        QueryRun                queryRun;
        AgreementHeaderRecId    agreementHeaderRecId;
        queryRun = new QueryRun(AgreementHeader::partyAgreementsQuery(tableNum(SalesAgreementHeader), fieldNum(SalesAgreementHeader, CustAccount),
            _custAccount, _shippingDateRequested, true));
        
        if(queryRun.next())
        {
            SalesAgreementHeader salesAgreementHeader = queryRun.get(tableNum(SalesAgreementHeader));
            agreementHeaderRecId = salesAgreementHeader.RecId;
        }

        return agreementHeaderRecId;
    }
